public static class Gfusetest {
    internal static int GuRect(emon.Port.Cells pa, int page, int flags, int fill, int x0, int y0, int x1, int y1) {
        // A painted box with no geometry kept (read by its box).
        int r = Evidence.PaNew(pa, page, Evidence.PaRect(), x0, y0, x1, y1);
        Evidence.PaSet(pa, r, Evidence.PfFlags(), flags);
        Evidence.PaSet(pa, r, Evidence.PfFill(), fill);
        return r;
    }
    [Xunit.Fact]
    public static void TestTheRowsOfAVectorOnlyPage() {
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells mk = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells grl = emon.Port.NewCells();
        emon.Port.Cells gfl = emon.Port.NewCells();
        emon.Port.Cells cand = emon.Port.NewCells();
        emon.Port.Cells refs = emon.Port.NewCells();
        emon.Port.Cells ggp = emon.Port.NewCells();
        emon.Port.Cells grg = emon.Port.NewCells();
        int h = GuRect(pa, 1, Evidence.PgFilled(), 0, 1000, 4950, 21000, 5050);
        int v = GuRect(pa, 1, Evidence.PgFilled(), 0, 1000, 5000, 1100, 9000);
        int b = GuRect(pa, 1, Evidence.PgFilled(), 0, 1000, 6950, 21000, 7050);
        int x = GuRect(pa, 1, Evidence.PgFilled(), 0, 1000, 8950, 21000, 9050);
        int f = GuRect(pa, 1, Evidence.PgFilled(), 14540253, 2000, 12000, 12000, 15000);
        int p = GuRect(pa, 1, Evidence.PgFilled() + Evidence.PgPattern(), -1, 3000, 12000, 8000, 15000);
        int q = GuRect(pa, 2, Evidence.PgFilled(), 0, 1000, 9950, 21000, 10050);
        emon.Testport.AssertThat((v + (f + (p + q))) > 0, "the other paths are painted");
        Evidence.PaSet(pa, b, Evidence.PfVchk(), Evidence.VcBlend());
        Evidence.PaSet(pa, x, Evidence.PfVis(), 3);
        Evidence.PaSet(pa, h, Evidence.PfZ(), 4);
        emon.Testport.AssertEq(Gfuse.GfDoc(pa, pts, mk, im, 2, Gvec.GvSegments(), grl, gfl, cand), 4, "four rules: the hidden one is nothing");
        emon.Testport.AssertEq(Glayer.GflCount(gfl), 2, "two fills");
        emon.Testport.AssertEq(Glayer.GlCheck(grl, gfl, ggp, grg, refs), 0, "sound");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 0), 1, "the first rule's page");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 5), 1000, "its centre line starts at its left end");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 6), 5000, "on its centre");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 9), 100, "one point thick");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 10), Glayer.GoH(), "horizontal");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 11), 0, "at angle 0");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 12), 0, "black");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 14), 1, "from the vector source");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 15), 1, "which is the winner");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 16), 501, "by rule 501");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 17), 900, "at 900");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 19), -1, "no group before P7.G");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 20), 4, "its path's z");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 1, 10), Glayer.GoV(), "the second is vertical");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 1, 11), 9000, "at 9000");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 1, 5), 1050, "on its centre");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 2, 16), 514, "blended paint is not exactly known");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 2, 17), 700, "700");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 3, 0), 2, "the fourth is on page 2");
        emon.Testport.AssertEq(Glayer.GflGet(gfl, 0, 9), 560, "a fill by 560");
        emon.Testport.AssertEq(Glayer.GflGet(gfl, 0, 10), 900, "at 900");
        emon.Testport.AssertEq(Glayer.GflGet(gfl, 0, 5), 14540253, "its colour");
        emon.Testport.AssertEq(Glayer.GflGet(gfl, 0, 6), 866, "its lightness");
        emon.Testport.AssertEq(Glayer.GflGet(gfl, 1, 9), 562, "a pattern fill by 562");
        emon.Testport.AssertEq(Glayer.GflGet(gfl, 1, 10), 600, "at 600");
        emon.Testport.AssertEq(Glayer.GflGet(gfl, 1, 5), -1, "of no colour");
        emon.Testport.AssertEq(Glayer.GflGet(gfl, 1, 11), Glayer.GqfPattern(), "flagged pattern");
    }
    [Xunit.Fact]
    public static void TestASlantedLineIsASlantAndTheModesAgreeOnPlainBoxes() {
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells pts = emon.Port.NewCells();
        emon.Port.Cells mk = emon.Port.NewCells();
        emon.Port.Cells im = emon.Port.NewCells();
        emon.Port.Cells grl = emon.Port.NewCells();
        emon.Port.Cells gfl = emon.Port.NewCells();
        emon.Port.Cells cand = emon.Port.NewCells();
        int r = Evidence.PaNew(pa, 1, Evidence.PaOther(), 0, 0, 10000, 10000);
        Evidence.PaSet(pa, r, Evidence.PfFlags(), Evidence.PgStroked());
        Evidence.PaSet(pa, r, Evidence.PfStroke(), 0);
        Evidence.PaSet(pa, r, Evidence.PfWidth(), 50);
        Evidence.PaSet(pa, r, Evidence.PfPfirst(), 0);
        Evidence.PaSet(pa, r, Evidence.PfPcount(), 2);
        Evidence.PtAdd(pts, 0, 0, Evidence.PoMove());
        Evidence.PtAdd(pts, 10000, 10000, Evidence.PoLine());
        emon.Testport.AssertEq(Gfuse.GfDoc(pa, pts, mk, im, 1, Gvec.GvSegments(), grl, gfl, cand), 1, "one rule");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 10), Glayer.GoSlant(), "slanted");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 11), 13500, "at 135 degrees (page space has y down)");
        // a plain thin box: the two modes give the same row
        emon.Port.CellsDrop(pa, 0);
        GuRect(pa, 1, Evidence.PgFilled(), 0, 1000, 4950, 21000, 5050);
        emon.Testport.AssertEq(Gfuse.GfDoc(pa, pts, mk, im, 1, Gvec.GvLegacy(), grl, gfl, cand), 1, "legacy: one rule");
        int a = Glayer.GrlGet(grl, 0, 5);
        int b = Glayer.GrlGet(grl, 0, 7);
        int c = Glayer.GrlGet(grl, 0, 6);
        emon.Testport.AssertEq(Gfuse.GfDoc(pa, pts, mk, im, 1, Gvec.GvSegments(), grl, gfl, cand), 1, "segments: one rule");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 5), a, "the same left end");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 7), b, "the same right end");
        emon.Testport.AssertEq(Glayer.GrlGet(grl, 0, 6), c, "the same centre");
    }
